# 10 autotune configs, XBLOCK>=64, YBLOCK<=32, num_stages 2-3
@triton.autotune(configs=[...10 configs...], key=['ynumel','xnumel'])
@triton.jit
def kernel(...):
    tmp0 = tl.load(in_ptr + load_idx, mask, eviction_policy='evict_first')
    tl.store(out_ptr + (y0 + 3*x2 + stride*y1), tmp0, mask)  # no eviction hint on store

